solution:
def is_valid_ipv4(address):
    parts = address.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not 1 <= len(part) <= 3:
            return False                       # empty, or too long to be 0-255
        if any(char not in "0123456789" for char in part):
            return False                       # ASCII digits only: no signs, spaces or other alphabets
        if part[0] == "0" and len(part) > 1:
            return False                       # no leading zeros
        if int(part) > 255:
            return False
    return True
